1	package clinical
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"reflect"
8		"testing"
9		"time"
10	)
11	
12	// TestActivationSaveFailureKeepsDraftAndAllowsRetry 覆盖“内部使用者提交、患者未
13	// 停用、目标记录仍是草稿，同一次就诊已有同类生效记录，但本地保存失败”的生效场景：
14	// 生效必须把草稿固化为第 1 版、清除草稿并留下生效审计，三者作为同一次成功操作
15	// 出现——保存失败时一项都不能单独成立。失败后目标草稿的标识、就诊归属、类别与
16	// 完整草稿内容原样保留，没有当前版本与历史版本，也没有新增生效审计；持有该就诊
17	// 该类别有效整类授权的接收方仍只能看到原先已生效的内容。保存条件恢复后同一条
18	// 草稿可以正常生效：版本号从 1 开始，内容与时间取自成功的这次提交；失败与成功
19	// 两种状态在关闭后重新打开同一数据位置时都保持一致。诊断与医嘱同样适用。
20	func TestActivationSaveFailureKeepsDraftAndAllowsRetry(t *testing.T) {
21		for _, category := range []string{Diagnosis, Order} {
22			t.Run(category, func(t *testing.T) {
23				testActivationSaveFailure(t, category)
24			})
25		}
26	}
27	
28	func testActivationSaveFailure(t *testing.T, category string) {
29		dir := t.TempDir()
30		clk := &fakeClock{t: time.Date(2026, 7, 1, 9, 0, 0, 0, time.UTC)}
31		open := func() *Store {
32			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
33			if err != nil {
34				t.Fatalf("open: %v", err)
35			}
36			return s
37		}
38	
39		s := open()
40		p, err := s.RegisterPatient(doc, "生效保存失败患者")
41		if err != nil {
42			t.Fatal(err)
43		}
44		e, err := s.AddEncounter(doc, p.ID, time.Time{})
45		if err != nil {
46			t.Fatal(err)
47		}
48		// 同一次就诊下已有一条同类别的生效记录。
49		otherContent := "既有生效内容-" + category
50		other, err := s.CreateDraft(doc, p.ID, e.ID, category, otherContent)
51		if err != nil {
52			t.Fatal(err)
53		}
54		otherV1, err := s.ActivateRecord(doc, other.ID)
55		if err != nil {
56			t.Fatal(err)
57		}
58		// 目标记录仍是草稿。
59		draftContent := "目标草稿内容-" + category
60		target, err := s.CreateDraft(doc, p.ID, e.ID, category, draftContent)
61		if err != nil {
62			t.Fatal(err)
63		}
64		// 接收方持有该就诊该类别当前有效的整类授权。
65		if _, err := s.Grant(doc, p.ID, rcv.ID,
66			[]Scope{{EncounterID: e.ID, Category: category}},
67			clk.t.Add(-time.Hour), clk.t.Add(48*time.Hour)); err != nil {
68			t.Fatal(err)
69		}
70	
71		// 提交前的基线：目标草稿、既有记录历史、审计与接收方读取结果。
72		chartBefore, err := s.Chart(doc, p.ID)
73		if err != nil {
74			t.Fatal(err)
75		}
76		targetBefore := findHistory(chartBefore, target.ID)
77		if targetBefore == nil || !targetBefore.HasDraft || targetBefore.DraftContent != draftContent ||
78			targetBefore.CurrentVersion != nil || len(targetBefore.Versions) != 0 {
79			t.Fatalf("unexpected baseline target draft: %+v", targetBefore)
80		}
81		otherHistBefore := findHistory(chartBefore, other.ID)
82		if otherHistBefore == nil || otherHistBefore.CurrentVersion == nil ||
83			otherHistBefore.CurrentVersion.ID != otherV1.ID || len(otherHistBefore.Versions) != 1 {
84			t.Fatalf("unexpected baseline other history: %+v", otherHistBefore)
85		}
86		auditBefore, err := s.AuditEvents(doc, p.ID)
87		if err != nil {
88			t.Fatal(err)
89		}
90		if got := auditActions(auditBefore); got[ActionActivated] != 1 || got[ActionGranted] != 1 {
91			t.Fatalf("unexpected baseline audit: %v", got)
92		}
93		readBefore, err := s.Read(rcv, p.ID, e.ID, category)
94		if err != nil {
95			t.Fatal(err)
96		}
97		if len(readBefore.Records) != 1 || readBefore.Records[0].RecordID != other.ID ||
98			readBefore.Records[0].VersionID != otherV1.ID || readBefore.Records[0].Content != otherContent {
99			t.Fatalf("unexpected baseline read: %+v", readBefore)
100		}
101	
102		// checkIntact 断言：失败尝试之后（以及重开之后），目标记录仍是提交前的那条
103		// 草稿——标识、就诊归属、类别与完整草稿内容都在，仍没有当前生效版本与任何
104		// 历史版本；既有记录、审计与接收方可见结果全部维持提交前状态，没有新增
105		// 目标记录的生效事件，目标草稿也没有被计为新增生效记录。
106		checkIntact := func(label string, st *Store) {
107			t.Helper()
108	
109			chart, err := st.Chart(doc, p.ID)
110			if err != nil {
111				t.Fatalf("%s: chart: %v", label, err)
112			}
113			hist := findHistory(chart, target.ID)
114			if hist == nil {
115				t.Fatalf("%s: target record missing", label)
116			}
117			if hist.Record.ID != target.ID || hist.Record.PatientID != p.ID ||
118				hist.Record.EncounterID != e.ID || hist.Record.Category != category {
119				t.Fatalf("%s: target record identity changed: %+v", label, hist.Record)
120			}
121			if !hist.HasDraft || hist.DraftContent != draftContent ||
122				hist.Record.DraftContent != draftContent || !hist.Record.HasDraft {
123				t.Fatalf("%s: draft content lost or changed: %+v", label, hist)
124			}
125			if hist.CurrentVersion != nil || hist.Record.CurrentVersionID != "" ||
126				len(hist.Versions) != 0 || len(hist.Record.Versions) != 0 {
127				t.Fatalf("%s: failed activation left a version: %+v", label, hist)
128			}
129			// 既有生效记录的历史原样保留。
130			if got := findHistory(chart, other.ID); !reflect.DeepEqual(got, otherHistBefore) {
131				t.Fatalf("%s: other record history changed:\nbefore: %+v\nafter:  %+v", label, otherHistBefore, got)
132			}
133	
134			// 就诊视图中的目标记录同样仍是草稿。
135			er, err := st.EncounterRecords(doc, p.ID, e.ID)
136			if err != nil {
137				t.Fatalf("%s: encounter records: %v", label, err)
138			}
139			if len(er) != 2 {
140				t.Fatalf("%s: encounter record count changed: %+v", label, er)
141			}
142			for _, rh := range er {
143				if rh.Record.ID == target.ID && (!rh.HasDraft || rh.CurrentVersion != nil) {
144					t.Fatalf("%s: target no longer a plain draft in encounter view: %+v", label, rh)
145				}
146			}
147	
148			// 既有审计事件保持原样，失败生效没有新增目标记录的生效事件。
149			audit, err := st.AuditEvents(doc, p.ID)
150			if err != nil {
151				t.Fatalf("%s: audit: %v", label, err)
152			}
153			if !reflect.DeepEqual(audit, auditBefore) {
154				t.Fatalf("%s: audit events changed:\nbefore: %+v\nafter:  %+v", label, auditBefore, audit)
155			}
156	
157			// 接收方仍只读到原先已生效的内容：失败尝试的内容、版本标识都不出现，
158			// 目标草稿也没有被计为新增生效记录。
159			res, err := st.Read(rcv, p.ID, e.ID, category)
160			if err != nil {
161				t.Fatalf("%s: receiver read: %v", label, err)
162			}
163			if !reflect.DeepEqual(res, readBefore) {
164				t.Fatalf("%s: receiver read changed:\nbefore: %+v\nafter:  %+v", label, readBefore, res)
165			}
166			if readRecordIDs(res)[target.ID] {
167				t.Fatalf("%s: failed activation leaked the target draft to the receiver", label)
168			}
169		}
170	
171		// 制造本地保存失败：数据文件原位置被同名目录占据，原子改名必然失败，
172		// 与身份、患者状态或参数合法性无关。原数据文件先挪到旁边，事后原样还原。
173		dataPath := filepath.Join(dir, dataName)
174		backupPath := dataPath + ".saved"
175		if err := os.Rename(dataPath, backupPath); err != nil {
176			t.Fatalf("backup data file: %v", err)
177		}
178		if err := os.Mkdir(dataPath, 0o755); err != nil {
179			t.Fatalf("block data path: %v", err)
180		}
181	
182		// 身份有权、患者未停用、目标记录仍是草稿，仅保存失败：明确报错，
183		// 且不能伪装成参数不合法、已生效或权限拒绝等业务结果。
184		failTime := clk.t.Add(time.Hour)
185		clk.t = failTime
186		if _, err := s.ActivateRecord(doc, target.ID); err == nil {
187			t.Fatal("activation must fail when local save fails")
188		} else if errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrActive) ||
189			errors.Is(err, ErrAccessDenied) || errors.Is(err, ErrDeactivated) ||
190			errors.Is(err, ErrNotFound) || errors.Is(err, ErrConflict) {
191			t.Fatalf("save failure surfaced as a business error: %v", err)
192		}
193		// 失败不能留下半截写入的临时文件。
194		if _, statErr := os.Stat(dataPath + ".tmp"); !os.IsNotExist(statErr) {
195			t.Fatalf("failed save left a temp file: %v", statErr)
196		}
197	
198		// 失败后：草稿、既有记录、审计与接收方读取全部维持提交前状态。
199		checkIntact("after failed save", s)
200	
201		// 关闭后从原数据位置重新打开：先恢复保存条件（还原原数据文件），
202		// 失败后的未生效状态在重开后保持一致。
203		if err := s.Close(); err != nil {
204			t.Fatal(err)
205		}
206		if err := os.Remove(dataPath); err != nil {
207			t.Fatalf("unblock data path: %v", err)
208		}
209		if err := os.Rename(backupPath, dataPath); err != nil {
210			t.Fatalf("restore data file: %v", err)
211		}
212		s2 := open()
213		checkIntact("after reopen", s2)
214	
215		// 保存条件恢复后：同一条草稿仍可修改并正常生效。版本内容必须取自这次
216		// 实际提交时的草稿，先生效时间属于成功的这次操作。
217		retryContent := "重试时提交的内容-" + category
218		if _, err := s2.UpdateDraft(doc, target.ID, retryContent); err != nil {
219			t.Fatalf("update draft after save recovered: %v", err)
220		}
221		successTime := failTime.Add(time.Hour)
222		clk.t = successTime
223		v1, err := s2.ActivateRecord(doc, target.ID)
224		if err != nil {
225			t.Fatalf("activate after save recovered: %v", err)
226		}
227		if v1.Number != 1 || v1.RecordID != target.ID || v1.Category != category ||
228			v1.Content != retryContent || v1.PrevID != "" || v1.Reason != "" {
229			t.Fatalf("bad v1: %+v", v1)
230		}
231		// 生效时间属于成功的这次操作，不能沿用失败尝试的时间。
232		if !v1.CreatedAt.Equal(successTime) || v1.CreatedAt.Equal(failTime) {
233			t.Fatalf("effective time %v does not belong to the successful attempt (failed at %v)", v1.CreatedAt, failTime)
234		}
235	
236		// 内部档案：草稿已清除，当前版本与唯一历史版本一致。
237		chart, err := s2.Chart(doc, p.ID)
238		if err != nil {
239			t.Fatal(err)
240		}
241		hist := findHistory(chart, target.ID)
242		if hist == nil || hist.CurrentVersion == nil {
243			t.Fatalf("history missing after retry: %+v", hist)
244		}
245		if hist.HasDraft || hist.DraftContent != "" || hist.Record.HasDraft || hist.Record.DraftContent != "" {
246			t.Fatalf("draft not cleared after activation: %+v", hist)
247		}
248		if !reflect.DeepEqual(*hist.CurrentVersion, v1) || hist.Record.CurrentVersionID != v1.ID {
249			t.Fatalf("current version mismatch: %+v vs %+v", hist.CurrentVersion, v1)
250		}
251		if len(hist.Versions) != 1 || !reflect.DeepEqual(hist.Versions[0], v1) ||
252			!reflect.DeepEqual(hist.Record.Versions, []ID{v1.ID}) {
253			t.Fatalf("history versions wrong after retry: %+v", hist)
254		}
255		// 既有记录的历史不受目标记录生效影响。
256		if got := findHistory(chart, other.ID); !reflect.DeepEqual(got, otherHistBefore) {
257			t.Fatalf("other record history changed by retry:\nbefore: %+v\nafter:  %+v", otherHistBefore, got)
258		}
259	
260		// 只多出一条生效审计：身份与对象对应本次提交，时间属于成功操作。
261		audit, err := s2.AuditEvents(doc, p.ID)
262		if err != nil {
263			t.Fatal(err)
264		}
265		if len(audit) != len(auditBefore)+1 || !reflect.DeepEqual(audit[:len(auditBefore)], auditBefore) {
266			t.Fatalf("audit after retry:\nbefore: %+v\nafter:  %+v", auditBefore, audit)
267		}
268		last := audit[len(audit)-1]
269		if last.Action != ActionActivated || last.ObjectType != "record" || last.ObjectID != target.ID ||
270			last.ActorID != doc.ID || last.PatientID != p.ID || !last.OccurredAt.Equal(successTime) {
271			t.Fatalf("unexpected new audit event: %+v", last)
272		}
273		if got := auditActions(audit)[ActionActivated]; got != 2 {
274			t.Fatalf("activated events = %d, want 2", got)
275		}
276	
277		// 仍有效的整类授权此时让接收方读到该版本；既有内容原样保留。
278		res, err := s2.Read(rcv, p.ID, e.ID, category)
279		if err != nil {
280			t.Fatal(err)
281		}
282		if len(res.Records) != 2 {
283			t.Fatalf("receiver read after retry = %+v, want 2 records", res)
284		}
285		byID := map[ID]EffectiveRecord{}
286		for _, rec := range res.Records {
287			byID[rec.RecordID] = rec
288		}
289		if got := byID[target.ID]; got.VersionID != v1.ID || got.Version != 1 ||
290			got.Content != retryContent || !got.EffectiveAt.Equal(successTime) {
291			t.Fatalf("receiver sees wrong target version: %+v", got)
292		}
293		if got := byID[other.ID]; got.VersionID != otherV1.ID || got.Content != otherContent {
294			t.Fatalf("receiver view of existing record changed: %+v", got)
295		}
296	
297		// 成功后的生效状态在关闭后重新打开同一数据位置时保持一致。
298		if err := s2.Close(); err != nil {
299			t.Fatal(err)
300		}
301		s3 := open()
302		t.Cleanup(func() { _ = s3.Close() })
303		chart, err = s3.Chart(doc, p.ID)
304		if err != nil {
305			t.Fatal(err)
306		}
307		hist = findHistory(chart, target.ID)
308		if hist == nil || hist.CurrentVersion == nil || !reflect.DeepEqual(*hist.CurrentVersion, v1) ||
309			len(hist.Versions) != 1 || hist.HasDraft {
310			t.Fatalf("activated state not preserved after reopen: %+v", hist)
311		}
312		audit, err = s3.AuditEvents(doc, p.ID)
313		if err != nil {
314			t.Fatal(err)
315		}
316		if got := auditActions(audit)[ActionActivated]; got != 2 {
317			t.Fatalf("activated events after reopen = %d, want 2", got)
318		}
319		res, err = s3.Read(rcv, p.ID, e.ID, category)
320		if err != nil {
321			t.Fatal(err)
322		}
323		if len(res.Records) != 2 || !readRecordIDs(res)[target.ID] {
324			t.Fatalf("receiver read after reopen = %+v, want activated target included", res)
325		}
326	
327		// 成功后再次要求同一记录生效：返回 ErrActive，不能生成第二个版本、
328		// 恢复草稿或追加审计。
329		if _, err := s3.ActivateRecord(doc, target.ID); !errors.Is(err, ErrActive) {
330			t.Fatalf("re-activate err = %v, want ErrActive", err)
331		}
332		chart, err = s3.Chart(doc, p.ID)
333		if err != nil {
334			t.Fatal(err)
335		}
336		hist = findHistory(chart, target.ID)
337		if hist == nil || len(hist.Versions) != 1 || hist.CurrentVersion == nil ||
338			hist.CurrentVersion.ID != v1.ID || hist.HasDraft || hist.DraftContent != "" {
339			t.Fatalf("re-activate changed the record: %+v", hist)
340		}
341		audit, err = s3.AuditEvents(doc, p.ID)
342		if err != nil {
343			t.Fatal(err)
344		}
345		if got := auditActions(audit)[ActionActivated]; got != 2 {
346			t.Fatalf("re-activate appended an audit event: activated = %d, want 2", got)
347		}
348	}
